ALTER TABLE "jobs" DROP CONSTRAINT "jobs_aspect_check";--> statement-breakpoint
ALTER TABLE "model_configs" DROP CONSTRAINT "model_configs_enabled_complete_check";--> statement-breakpoint
ALTER TABLE "jobs" ADD COLUMN "params" jsonb DEFAULT '{}' NOT NULL;--> statement-breakpoint
ALTER TABLE "model_configs" ADD COLUMN "kind" text DEFAULT 'video' NOT NULL;--> statement-breakpoint
ALTER TABLE "model_configs" ADD COLUMN "features" text[] DEFAULT '{video}' NOT NULL;--> statement-breakpoint
ALTER TABLE "model_configs" ADD COLUMN "image_prices" jsonb;--> statement-breakpoint
ALTER TABLE "jobs" ADD CONSTRAINT "jobs_aspect_check" CHECK ("jobs"."aspect" in ('auto', '1:1', '9:16', '16:9', '3:4', '4:3', '2:3', '3:2', '4:5', '5:4', '21:9'));--> statement-breakpoint
ALTER TABLE "model_configs" ADD CONSTRAINT "model_configs_kind_check" CHECK ("model_configs"."kind" in ('video', 'image'));--> statement-breakpoint
ALTER TABLE "model_configs" ADD CONSTRAINT "model_configs_enabled_complete_check" CHECK (not "model_configs"."enabled" or ("model_configs"."kind" = 'video' and "model_configs"."usd_per_second" is not null and "model_configs"."max_images" is not null and "model_configs"."output_resolution" is not null and cardinality("model_configs"."ratios") > 0 and cardinality("model_configs"."durations_sec") > 0) or ("model_configs"."kind" = 'image' and "model_configs"."image_prices" is not null and "model_configs"."image_prices" <> '{}'::jsonb and "model_configs"."max_images" is not null and cardinality("model_configs"."ratios") > 0));--> statement-breakpoint
